require_once __DIR__ . '/includes/auth.php'; require_login(); $pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); if ($_POST['form_action']==='status') { $pdo->prepare('UPDATE blotters SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]); flash('success','Blotter case status updated.'); redirect('blotters.php'); } $caseNo='BLT-'.date('Y').'-'.str_pad((string)random_int(1,9999),3,'0',STR_PAD_LEFT); $pdo->prepare('INSERT INTO blotters (case_no,incident_type,complainant,respondent,location,incident_date,narrative,status,priority) VALUES (?,?,?,?,?,?,? ,\'Recorded\',?)')->execute([$caseNo,trim($_POST['incident_type']),trim($_POST['complainant']),trim($_POST['respondent']),trim($_POST['location']),str_replace('T',' ', $_POST['incident_date']),trim($_POST['narrative']),$_POST['priority']]); flash('success','New blotter case recorded.'); redirect('blotters.php'); }
$active=(int)$pdo->query("SELECT COUNT(*) FROM blotters WHERE status <> 'Resolved'")->fetchColumn(); $resolved=(int)$pdo->query("SELECT COUNT(*) FROM blotters WHERE status='Resolved'")->fetchColumn(); $cases=$pdo->query("SELECT b.*,(SELECT COUNT(*) FROM attachments a WHERE a.entity='blotter' AND a.entity_id=b.id) AS attachment_count FROM blotters b ORDER BY incident_date DESC")->fetchAll(); $selected=$cases[0]??null; $pageTitle='Blotter management'; $activePage='blotters'; require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Records / Incident desk</div><h1>Blotter management</h1><p>Record incidents clearly, protect sensitive details, and track follow-up actions.</p></div><a class="primary-button" href="blotters.php?action=new">＋ Record new incident</a></section><div class="stats-grid"><div class="stat-card"><div class="stat-icon amber">▣</div><span class="stat-label">Active cases</span><strong><?= $active ?></strong><small>Needs follow-up</small></div><div class="stat-card"><div class="stat-icon blue">◷</div><span class="stat-label">For follow-up</span><strong>5</strong><small>Scheduled this week</small></div><div class="stat-card"><div class="stat-icon mint">✓</div><span class="stat-label">Resolved cases</span><strong><?= $resolved ?></strong><small>All-time records</small></div><div class="stat-card"><div class="stat-icon violet">▤</div><span class="stat-label">Total cases</span><strong><?= count($cases) ?></strong><small>Protected records</small></div></div><?php if (($_GET['action'] ?? '')==='new'): ?><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Incident desk</div><h2>Record new incident</h2></div><a class="text-button" href="blotters.php">Close ×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="new"><label>Incident type<input name="incident_type" required placeholder="e.g. Noise disturbance"></label><label>Incident date<input type="datetime-local" name="incident_date" required value="<?= date('Y-m-d\TH:i') ?>"></label><label>Complainant<input name="complainant" required></label><label>Respondent<input name="respondent" required></label><label class="wide">Location<input name="location" required placeholder="Purok / street"></label><label>Priority<select name="priority"><option>Normal</option><option>High</option></select></label><label class="wide">Incident narrative<textarea name="narrative" rows="4" required></textarea></label><div class="form-actions"><a class="secondary-button" href="blotters.php">Cancel</a><button class="primary-button">Save blotter case</button></div></form></section><?php endif; ?><div class="content-two-col"><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Incident registry</div><h2>Blotter cases</h2></div><span class="muted"><?= count($cases) ?> records</span></div><div class="table-wrap"><table><thead><tr><th>Case / incident</th><th>Parties</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach ($cases as $case): ?><tr><td><strong class="mono"><?= h($case['case_no']) ?></strong><small class="cell-subtext"><?= h($case['incident_type']) ?><?php if((int)($case['attachment_count']??0)>0): ?> · <?= h($case['attachment_count']) ?> attachment(s)<?php endif; ?></small></td><td><?= h($case['complainant']) ?><small class="cell-subtext">vs. <?= h($case['respondent']) ?></small></td><td class="muted"><?= h(date('M d, Y',strtotime($case['incident_date']))) ?></td><td><span class="status-pill <?= h(strtolower(str_replace(' ','-',$case['status']))) ?>"><i></i><?= h($case['status']) ?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="status"><input type="hidden" name="id" value="<?= h($case['id']) ?>"><select name="status" onchange="this.form.submit()"><option <?= $case['status']==='Recorded'?'selected':'' ?>>Recorded</option><option <?= $case['status']==='Pending'?'selected':'' ?>>Pending</option><option <?= $case['status']==='For review'?'selected':'' ?>>For review</option><option <?= $case['status']==='Resolved'?'selected':'' ?>>Resolved</option></select></form></td></tr><?php endforeach; ?></tbody></table></div></section><aside class="panel detail-panel"><div class="eyebrow">Selected case</div><?php if ($selected): ?><h2 class="mono big-mono"><?= h($selected['case_no']) ?></h2><span class="status-pill <?= h(strtolower(str_replace(' ','-',$selected['status']))) ?>"><i></i><?= h($selected['status']) ?></span><div class="detail-grid"><div><small>Incident type</small><strong><?= h($selected['incident_type']) ?></strong></div><div><small>Priority</small><strong><?= h($selected['priority']) ?></strong></div><div><small>Complainant</small><strong><?= h($selected['complainant']) ?></strong></div><div><small>Location</small><strong><?= h($selected['location']) ?></strong></div></div><div class="case-note"><div class="eyebrow">Incident narrative</div><p><?= h($selected['narrative']) ?></p></div><div class="timeline"><div class="timeline-item"><b>✓</b><div><strong>Incident recorded</strong><small><?= h(date('M d, Y h:i A',strtotime($selected['incident_date']))) ?></small></div></div><div class="timeline-item"><b>◷</b><div><strong>Follow-up assignment</strong><small>Review with barangay desk</small></div></div></div><?php else: ?><p class="muted">No cases recorded yet.</p><?php endif; ?></aside></div><?php require __DIR__.'/partials/footer.php'; ?>
